from decimal import Decimal

def recalculate_debt(fortnights: list[dict], ato_annual_income: Decimal | None) -> dict:
    total_debt = Decimal('0.00')
    has_missing_payslips = any(f.get('payslip_income') is None for f in fortnights)

    if has_missing_payslips:
        if ato_annual_income is None:
            return {'status': 'CANNOT_DETERMINE', 'debt': Decimal('0.00')}
        fortnightly_income = ato_annual_income / Decimal('26')
    else:
        fortnightly_income = None

    for f in fortnights:
        if not f.get('on_benefit', False):
            continue
        income = fortnightly_income if fortnightly_income is not None else f.get('payslip_income', Decimal('0.00'))
        paid = f.get('paid', Decimal('0.00'))
        is_carer = f.get('is_principal_carer', False)

        free_area = Decimal('100.00')
        excess = max(Decimal('0.00'), income - free_area)

        if is_carer:
            reduction = excess * Decimal('0.40')
        else:
            lower_excess = min(excess, Decimal('150.00'))
            upper_excess = max(Decimal('0.00'), excess - Decimal('150.00'))
            reduction = (lower_excess * Decimal('0.50')) + (upper_excess * Decimal('0.60'))

        debt = min(paid, reduction)
        total_debt += debt

    return {'status': 'OK', 'debt': total_debt.quantize(Decimal('0.01'))}

