            continue
        income = f.get('payslip_income', Decimal('0.00'))
        paid = f.get('paid', Decimal('0.00'))
        is_carer = f.get('is_principal_carer', False)

        free_area = Decimal('100.00')
        excess = max(Decimal('0.00'), income - free_area)

        if is_carer:
            reduction = excess * Decimal('0.40')
